class Solution {
  public boolean canMakeSquare(char[][] grid) {
    for (int r = 0; r < 2; r++)
      for (int c = 0; c < 2; c++) {
        int black = 0, white = 0;
        for (int i = r; i < r + 2; i++)
          for (int j = c; j < c + 2; j++) {
            if (grid[i][j] == 'B') black++;
            else white++;
          }
        if (black >= 3 || white >= 3) return true;
      }
    return false;
  }
}
